/* Pressure Ratings dashboard. Reads window.RR_DATA (data.js, generated by pipeline/export_dashboard.py). */
(function () {
  "use strict";
  const D = window.RR_DATA;
  const NS = "http://www.w3.org/2000/svg";
  const $ = (s) => document.querySelector(s);
  const state = { role: "batters", sel: { batters: null, bowlers: null }, sort: { key: "rank", dir: 1 }, q: "" };

  // ---------- formatting
  const nf = new Intl.NumberFormat("en-GB");
  const f = (v, d = 2) => (v == null ? "–" : Number(v).toFixed(d));
  const sgn = (v, d = 3) => (v == null ? "–" : (v > 0 ? "+" : v < 0 ? "−" : "") + Math.abs(v).toFixed(d));
  const pct = (v, d = 0) => (v == null ? "–" : (v * 100).toFixed(d) + "%");
  const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));

  // ---------- svg helpers
  function el(tag, attrs, parent) {
    const n = document.createElementNS(NS, tag);
    for (const k in attrs || {}) n.setAttribute(k, attrs[k]);
    if (parent) parent.appendChild(n);
    return n;
  }
  function svg(container, w, h) {
    container.innerHTML = "";
    return el("svg", { viewBox: `0 0 ${w} ${h}`, role: "img", preserveAspectRatio: "xMidYMid meet" }, container);
  }
  function text(parent, x, y, s, attrs) {
    const t = el("text", Object.assign({ x, y }, attrs || {}), parent);
    t.textContent = s;
    return t;
  }
  const cw = (sel) => Math.max(300, Math.round($(sel).clientWidth || 600)); // chart width = container width
  const lin = (d0, d1, r0, r1) => (v) => r0 + ((v - d0) / (d1 - d0)) * (r1 - r0);
  function niceTicks(lo, hi, n) {
    const span = hi - lo, step0 = span / n, mag = Math.pow(10, Math.floor(Math.log10(step0)));
    const step = [1, 2, 2.5, 5, 10].map((m) => m * mag).find((s) => span / s <= n) || 10 * mag;
    const out = [];
    for (let v = Math.ceil(lo / step) * step; v <= hi + 1e-9; v += step) out.push(+v.toFixed(10));
    return out;
  }

  // ---------- tooltip
  const tip = $("#tip");
  function showTip(html, ev) {
    tip.innerHTML = html;
    tip.hidden = false;
    moveTip(ev);
  }
  function moveTip(ev) {
    const pad = 14, r = tip.getBoundingClientRect();
    let x = ev.clientX + pad, y = ev.clientY + pad;
    if (x + r.width > innerWidth - 8) x = ev.clientX - r.width - pad;
    if (y + r.height > innerHeight - 8) y = ev.clientY - r.height - pad;
    tip.style.left = Math.max(8, x) + "px";
    tip.style.top = Math.max(8, y) + "px";
  }
  const hideTip = () => (tip.hidden = true);
  function hover(node, html) {
    node.addEventListener("mouseenter", (e) => showTip(typeof html === "function" ? html() : html, e));
    node.addEventListener("mousemove", moveTip);
    node.addEventListener("mouseleave", hideTip);
    node.addEventListener("click", (e) => showTip(typeof html === "function" ? html() : html, e));
  }

  const players = () => D[state.role];
  const isBat = () => state.role === "batters";
  const variantsOf = (p) => D.variants.map((v) => ({ label: v.label, r: p[v.key] }));

  // ---------- header
  function header() {
    const m = D.meta;
    $("#k-balls").textContent = nf.format(m.balls);
    $("#k-matches").textContent = nf.format(m.matches);
    $("#k-years").textContent = `${m.years[0]}–${m.years[m.years.length - 1]}`;
    const k = [
      [pct(m.hp_move_share), `of all the swing in win probability happens on the ${pct(m.hp_ball_share)} of balls rated high pressure`],
      [pct(m.decided.model_high_share_decided, 2), `of high-pressure balls come from matches already decided, against a ${pct(m.decided.all_balls_share_decided)} base rate`],
      [`${D.reliability.batters.eligible} + ${D.reliability.bowlers.eligible}`, `eligible batters and bowlers, each re-ranked under ${D.variants.length} alternative methods`],
    ];
    $("#kpis").innerHTML = k.map(([v, l]) => `<div><div class="v">${v}</div><div class="l">${l}</div></div>`).join("");
    const a = $("#repo-link");
    a.href = m.repo;
    a.textContent = m.repo.replace("https://", "");
  }

  // ---------- top-10 rating chart
  function rateChart() {
    const top = players().slice(0, 10);
    const W = cw("#rate-chart"), rowH = 38, padT = 20, padB = 34, labW = W < 480 ? 176 : 172, padR = W < 480 ? 40 : 70;
    const H = padT + rowH * top.length + padB;
    const lo = Math.min(0, ...top.map((p) => p.rating_lo)), hi = Math.max(...top.map((p) => p.rating_hi));
    const x = lin(lo, hi * 1.04, labW, W - padR);
    const s = svg($("#rate-chart"), W, H);
    s.setAttribute("aria-label", `Top 10 ${state.role}: rating with 20th to 80th percentile range`);
    const ticks = niceTicks(lo, hi, W < 480 ? 3 : 5);
    ticks.forEach((t) => {
      el("line", { x1: x(t), x2: x(t), y1: padT, y2: H - padB, class: t === 0 ? "zero" : "gridline" }, s);
      text(s, x(t), H - padB + 18, t.toFixed(2), { "text-anchor": "middle" });
    });
    text(s, (labW + W - padR) / 2, H - 1, "Pressure rating", { "text-anchor": "middle", fill: "var(--muted)" });
    top.forEach((p, i) => {
      const cy = padT + rowH * i + rowH / 2;
      const g = el("g", { class: "row-hit" + (state.sel[state.role] === p.pid ? " sel" : ""), tabindex: 0, role: "button", "data-pid": p.pid, "aria-pressed": String(state.sel[state.role] === p.pid), "aria-label": `${p.rank}. ${p.name}` }, s);
      el("rect", { x: 0, y: cy - rowH / 2 + 1, width: W, height: rowH - 2, rx: 8, class: "row-bg", fill: "transparent" }, g);
      text(g, 8, cy + 4, String(p.rank), { fill: "var(--muted)", "font-weight": 700 });
      text(g, 30, cy + 4, p.name, { class: "nm", "font-size": W < 480 ? 11.5 : 12.5 });
      el("line", { x1: x(p.rating_lo), x2: x(p.rating_hi), y1: cy, y2: cy, stroke: "var(--series-2)", "stroke-width": 6, "stroke-linecap": "round", opacity: 0.55 }, g);
      el("rect", { x: x(p.rating_lo) - 1.5, y: cy - 9, width: 3, height: 18, rx: 1.5, fill: "var(--navy)" }, g);
      el("circle", { cx: x(p.rating), cy, r: 5.5, fill: "var(--accent)", stroke: "var(--surface)", "stroke-width": 2 }, g);
      text(g, W - 4, cy + 4, `${Math.round(p.p_top10 * 100)}%`, { fill: "var(--ink-2)", "text-anchor": "end" });
      hover(g, () => `<b>${esc(p.name)}</b><br>Rating ${sgn(p.rating)}<br>Ranking value (20th pct) ${sgn(p.rating_lo)}<br>80th pct ${sgn(p.rating_hi)}<br>Chance of being top 10: ${pct(p.p_top10)}`);
      const pick = (e) => select(p.pid, e && e.type === "keydown");
      g.addEventListener("click", pick);
      g.addEventListener("keydown", (e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); pick(e); } });
    });
    text(s, W - 4, 12, "P(top 10)", { fill: "var(--muted)", "font-size": 10, "text-anchor": "end" });
    $("#rate-legend").innerHTML =
      '<span><i class="key dot" style="background:var(--accent)"></i>Rating (point estimate)</span>' +
      '<span><i class="key" style="background:var(--series-2);opacity:.55;width:22px;height:6px"></i>20th–80th percentile</span>' +
      '<span><i class="key tick" style="background:var(--navy)"></i>Ranking value (20th percentile)</span>';
  }

  // ---------- detail panel
  function detail() {
    const list = players();
    const p = list.find((x) => x.pid === state.sel[state.role]) || list[0];
    const bat = isBat();
    const rowsCmp = bat
      ? [["Strike rate", f(p.sr_hp, 0), f(p.sr_ord, 0)], ["Average", f(p.avg_hp, 1), f(p.avg_ord, 1)],
         ["Dot balls", pct(p.dot_pct_hp), pct(p.dot_pct_ord)], ["Boundary balls", pct(p.bnd_pct_hp), pct(p.bnd_pct_ord)],
         ["Impact per unit of stakes", sgn(p.pressure_raw), sgn(p.usual_raw)]]
      : [["Economy", f(p.econ_hp, 2), f(p.econ_ord, 2)], ["Balls per wicket", f(p.balls_per_wkt_hp, 0), f(p.balls_per_wkt_ord, 0)],
         ["Dot balls", pct(p.dot_pct_hp), pct(p.dot_pct_ord)], ["Boundary balls conceded", pct(p.bnd_pct_hp), pct(p.bnd_pct_ord)],
         ["Impact per unit of stakes", sgn(p.pressure_raw), sgn(p.usual_raw)]];
    const v = variantsOf(p);
    const flags = [];
    if (p.variants_top10 * 2 < p.variants_eligible && p.rank <= 10)
      flags.push(`Fragile pick: top 10 in only ${p.variants_top10} of ${p.variants_eligible} variants where eligible.`);
    if (p.best2_share_of_gains > 0.5)
      flags.push(`Over half of this player's gains come from their best two matches (${pct(p.best2_share_of_gains)}).`);
    const fmt = p.share_ipl_balls >= 0.995 ? "IPL only" : p.share_ipl_balls <= 0.005 ? "T20I only" : `${pct(p.share_ipl_balls)} IPL · ${pct(1 - p.share_ipl_balls)} T20I`;
    $("#detail").innerHTML = `
      <div class="d-top">
        <div>
          <div class="d-rank">Rank ${p.rank} of ${list.length} ${state.role}</div>
          <div class="d-name">${esc(p.name)}</div>
          <div class="d-meta">${p.first_year}–${p.last_year} · ${p.matches} matches · ${fmt}</div>
        </div>
        <div class="d-big"><div class="v">${sgn(p.rating)}</div><div class="l">pressure rating</div></div>
      </div>
      <div class="pills">
        <div class="pill"><div class="v">${pct(p.p_top10)}</div><div class="l">chance of being truly top 10</div></div>
        <div class="pill"><div class="v">${p.b_hi}</div><div class="l">high-pressure balls in ${p.hp_inns} innings</div></div>
        <div class="pill"><div class="v">${pct(p.share_positive_matches)}</div><div class="l">of pressure matches with a positive impact</div></div>
      </div>
      <table class="cmp"><thead><tr><th></th><th>High pressure</th><th>Ordinary</th></tr></thead><tbody>
        ${rowsCmp.map((r) => `<tr><td>${r[0]}</td><td class="hp">${r[1]}</td><td>${r[2]}</td></tr>`).join("")}
      </tbody></table>
      <p class="note">Uplift (pressure minus ordinary impact): ${sgn(p.uplift_raw)}. Uplift does not repeat across matches, so it
        carries little weight in the rating. ${pct(p.weight_on_pressure_balls)} of this player's own-data weight is on pressure balls.</p>
      <div class="d-sec">Rank under each alternative method · top 10 in ${p.variants_top10} of ${p.variants_eligible}</div>
      <div class="strip" id="strip">${v.map((x) => `<div class="${x.r == null ? "na" : x.r <= 10 ? "t10" : x.r <= 20 ? "t20" : ""}" data-l="${esc(x.label)}" data-r="${x.r == null ? "" : x.r}">${x.r == null ? "–" : x.r}</div>`).join("")}</div>
      ${flags.map((t) => `<div class="flag">${t}</div>`).join("")}`;
    document.querySelectorAll("#strip div").forEach((n) =>
      hover(n, () => `<b>${esc(n.dataset.l)}</b><br>${n.dataset.r ? "Rank " + n.dataset.r : "Not eligible in this variant"}`));
  }

  // ---------- player table
  function cols() {
    const c = [
      ["rank", "Rank", (p) => p.rank],
      ["name", "Player", (p) => esc(p.name) + (p.rank <= 10 ? '<span class="badge">TOP 10</span>' : "")],
      ["rating", "Rating", (p) => sgn(p.rating)],
      ["rating_lo", "Ranking value", (p) => sgn(p.rating_lo)],
      ["p_top10", "P(top 10)", (p) => `${pct(p.p_top10)}<span class="minibar" style="width:${Math.round(p.p_top10 * 40)}px"></span>`],
      ["b_hi", "Pressure balls", (p) => p.b_hi],
      ["hp_inns", "Inns", (p) => p.hp_inns],
    ];
    if (isBat()) c.push(["sr_hp", "SR press.", (p) => f(p.sr_hp, 0)], ["sr_ord", "SR ord.", (p) => f(p.sr_ord, 0)]);
    else c.push(["econ_hp", "Econ press.", (p) => f(p.econ_hp, 2)], ["econ_ord", "Econ ord.", (p) => f(p.econ_ord, 2)]);
    c.push(["uplift_raw", "Uplift", (p) => sgn(p.uplift_raw)], ["variants_top10", "Variants top 10", (p) => `${p.variants_top10}/${p.variants_eligible}`]);
    return c;
  }
  function table() {
    const c = cols(), { key, dir } = state.sort;
    const q = state.q.trim().toLowerCase();
    let rows = players().filter((p) => !q || p.name.toLowerCase().includes(q));
    rows = rows.slice().sort((a, b) => {
      const x = a[key], y = b[key];
      if (typeof x === "string") return dir * x.localeCompare(y);
      return dir * ((x ?? -Infinity) - (y ?? -Infinity)) || a.rank - b.rank;
    });
    const t = $("#ptable");
    t.innerHTML = `<thead><tr>${c.map(([k, l]) => `<th class="sortable" data-k="${k}"${k === key ? ` aria-sort="${dir > 0 ? "ascending" : "descending"}"` : ""}><button type="button" class="th-btn">${l}</button></th>`).join("")}</tr></thead>
      <tbody>${rows.length ? rows.map((p) => `<tr data-pid="${p.pid}" class="${p.rank <= 10 ? "top" : ""}">${c.map(([, , fn], i) => `<td>${i === 1 ? `<button type="button" class="link">${fn(p)}</button>` : fn(p)}</td>`).join("")}</tr>`).join("")
        : `<tr class="empty"><td colspan="${c.length}">No player matches “${esc(state.q)}”. <button type="button" class="link" id="clear-q">Clear search</button></td></tr>`}</tbody>`;
    const cq = $("#clear-q");
    if (cq) cq.addEventListener("click", () => { state.q = ""; $("#search").value = ""; table(); $("#search").focus(); });
    t.querySelectorAll("th").forEach((th) => th.querySelector("button").addEventListener("click", () => {
      const k = th.dataset.k;
      if (state.sort.key === k) state.sort.dir *= -1;
      else state.sort = { key: k, dir: k === "rank" || k === "name" ? 1 : -1 };
      table();
      t.querySelector(`th[data-k="${k}"] button`).focus();
    }));
    t.querySelectorAll("tbody tr[data-pid]").forEach((tr) => tr.addEventListener("click", () => openPlayer(+tr.dataset.pid)));
    $("#count").textContent = `${rows.length} of ${players().length} players`;
  }

  // ---------- heatmaps
  let heroDrawn = false;
  function heat(container, inn) {
    const g = D.grid.filter((r) => r.innings === inn);
    const hero = container.id === "heat-hero", animate = hero && !heroDrawn;
    if (hero) heroDrawn = true;
    const W = cw("#" + container.id), H = Math.round(Math.min(hero ? 460 : 340, Math.max(220, W * (hero ? 0.6 : 0.58)))), pl = 34, pb = 34, pt = 6, pr = 6;
    const cellW = (W - pl - pr) / 20, ch = (H - pt - pb) / 9;
    const s = svg(container, W, H);
    s.setAttribute("aria-label", `${inn === 1 ? "First innings" : "Chase"}: share of high-pressure balls by over and wickets down`);
    for (let w = 0; w <= 8; w++) text(s, pl - 8, H - pb - ch * w - ch / 2 + 4, String(w), { "text-anchor": "end" });
    [1, 5, 10, 15, 20].forEach((o) => text(s, pl + cellW * (o - 0.5), H - pb + 16, String(o), { "text-anchor": "middle" }));
    text(s, pl + (W - pl - pr) / 2, H - 2, "Over", { "text-anchor": "middle", fill: "var(--muted)" });
    const yl = text(s, 10, pt + (H - pt - pb) / 2, "Wickets down", { "text-anchor": "middle", fill: "var(--muted)" });
    yl.setAttribute("transform", `rotate(-90 10 ${pt + (H - pt - pb) / 2})`);
    g.forEach((r) => {
      if (r.wkts_before > 8) return;
      const k = Math.min(1, r.share_high / 0.8);
      const c = el("rect", {
        x: pl + cellW * (r.overid - 1) + 1.5, y: H - pb - ch * (r.wkts_before + 1) + 1.5, width: cellW - 3, height: ch - 3, rx: hero ? 4 : 3,
        style: `fill: color-mix(in oklab, var(--accent) ${Math.round(4 + k * 96)}%, var(--heat-base))` +
          (animate ? `; animation-delay: ${(0.45 + r.overid * 0.045 + r.wkts_before * 0.012).toFixed(3)}s` : ""),
      }, s);
      if (animate) c.classList.add("cell-in");
      hover(c, `<b>Over ${r.overid}, ${r.wkts_before} down</b><br>${pct(r.share_high)} of balls high pressure<br>${nf.format(r.n)} balls`);
    });
  }
  function heatScale() {
    $("#heat-scale").innerHTML = `<span>0%</span><span class="ramp" style="background:linear-gradient(90deg, color-mix(in oklab, var(--accent) 6%, var(--heat-base)), var(--accent))"></span><span>80%+ of balls high pressure</span>`;
  }

  // ---------- swing bars
  function swing() {
    const rows = [];
    ["IPL", "T20I"].forEach((fm) => [1, 2].forEach((inn) => {
      const o = D.validation.find((r) => r.fmt === fm && r.innings === inn && !r.high_pressure);
      const h = D.validation.find((r) => r.fmt === fm && r.innings === inn && r.high_pressure);
      rows.push({ fm, inn: inn === 1 ? "1st innings" : "Chase", label: `${fm} · ${inn === 1 ? "1st innings" : "chase"}`, o, h });
    }));
    const W = cw("#swing-chart"), H = 260, pl = 44, pb = 40, pt = 18, pr = 6;
    const s = svg($("#swing-chart"), W, H);
    s.setAttribute("aria-label", "Mean win-probability swing per ball, high-pressure vs ordinary");
    const max = Math.max(...rows.map((r) => r.h.mean_abs_wp_swing));
    const y = lin(0, max * 1.1, H - pb, pt);
    niceTicks(0, max * 1.1, 4).forEach((t) => {
      el("line", { x1: pl, x2: W - pr, y1: y(t), y2: y(t), class: t === 0 ? "zero" : "gridline" }, s);
      text(s, pl - 6, y(t) + 4, (t * 100).toFixed(1) + "%", { "text-anchor": "end" });
    });
    const band = (W - pl - pr) / rows.length, bw = Math.min(24, band / 3.2);
    rows.forEach((r, i) => {
      const cx = pl + band * i + band / 2;
      [[r.o, -1, "var(--series-2)"], [r.h, 1, "var(--accent)"]].forEach(([d, side, col]) => {
        const x0 = cx + (side < 0 ? -bw - 1 : 1), top = y(d.mean_abs_wp_swing), base = y(0);
        const p = el("path", { d: barPath(x0, top, bw, base - top), fill: col }, s);
        hover(p, `<b>${r.label} · ${d.high_pressure ? "high pressure" : "ordinary"}</b><br>Mean swing ${(d.mean_abs_wp_swing * 100).toFixed(2)}% win prob.<br>${nf.format(d.balls)} balls · wicket rate ${pct(d.wicket_rate, 1)}`);
      });
      const ratio = r.h.mean_abs_wp_swing / r.o.mean_abs_wp_swing;
      text(s, cx + 1 + bw / 2, y(r.h.mean_abs_wp_swing) - 6, ratio.toFixed(1) + "×", { "text-anchor": "middle", fill: "var(--ink)", "font-weight": 700 });
      text(s, cx, H - pb + 16, r.fm, { "text-anchor": "middle", fill: "var(--ink)" });
      text(s, cx, H - pb + 30, r.inn, { "text-anchor": "middle" });
    });
    $("#swing-legend").innerHTML = '<span><i class="key" style="background:var(--series-2)"></i>Ordinary balls</span><span><i class="key" style="background:var(--accent)"></i>High-pressure balls</span>';
  }
  function barPath(x, y, w, h) { // 4px rounded top, square base
    const r = Math.min(4, w / 2, h);
    return `M${x},${y + h}V${y + r}Q${x},${y} ${x + r},${y}H${x + w - r}Q${x + w},${y} ${x + w},${y + r}V${y + h}Z`;
  }

  // ---------- decided share (horizontal bars)
  function decided() {
    const d = D.meta.decided;
    const rows = [["Stakes definition (ours)", d.model_high_share_decided, "var(--accent)"],
                  ["All balls (base rate)", d.all_balls_share_decided, "var(--series-2)"],
                  ["Rule-based difficulty index", d.rule_high_share_decided, "var(--series-2)"]];
    const W = cw("#decided-chart"), narrow = W < 520, rowH = narrow ? 52 : 44, labW = narrow ? 0 : 200, pr = 60, H = rowH * rows.length + 6;
    const s = svg($("#decided-chart"), W, H);
    s.setAttribute("aria-label", "Share of flagged balls from already-decided matches");
    const x = lin(0, 0.22, labW, W - pr);
    rows.forEach(([l, v, c], i) => {
      const cy = rowH * i + rowH / 2 + (narrow ? 8 : 0);
      text(s, 0, narrow ? cy - 14 : cy + 4, l, { fill: "var(--ink)" });
      const w = Math.max(2, x(v) - labW);
      const p = el("path", { d: `M${labW},${cy - 9}H${labW + w - Math.min(4, w / 2)}Q${labW + w},${cy - 9} ${labW + w},${cy - 9 + Math.min(4, w / 2)}V${cy + 9 - Math.min(4, w / 2)}Q${labW + w},${cy + 9} ${labW + w - Math.min(4, w / 2)},${cy + 9}H${labW}Z`, fill: c }, s);
      hover(p, `<b>${l}</b><br>${pct(v, 2)} of flagged balls from decided matches`);
      text(s, labW + w + 8, cy + 4, pct(v, v < 0.01 ? 2 : 0), { fill: "var(--ink)", "font-weight": 700 });
    });
  }

  // ---------- calibration
  function calibration() {
    const W = cw("#cal-chart"), H = Math.round(Math.min(360, Math.max(260, W * 0.4))), pl = 44, pb = 36, pt = 10, pr = 10;
    const s = svg($("#cal-chart"), W, H);
    s.setAttribute("aria-label", "Calibration: predicted vs observed win rate");
    const x = lin(0, 1, pl, W - pr), y = lin(0, 1, H - pb, pt);
    [0, 0.25, 0.5, 0.75, 1].forEach((t) => {
      el("line", { x1: pl, x2: W - pr, y1: y(t), y2: y(t), class: "gridline" }, s);
      if (t > 0) text(s, pl - 6, y(t) + 4, pct(t), { "text-anchor": "end" });
      text(s, x(t), H - pb + 16, pct(t), { "text-anchor": "middle" });
    });
    text(s, (pl + W - pr) / 2, H - 2, "Predicted win probability", { "text-anchor": "middle", fill: "var(--muted)" });
    el("line", { x1: x(0), y1: y(0), x2: x(1), y2: y(1), stroke: "var(--muted)", "stroke-dasharray": "0", "stroke-width": 1, opacity: 0.6 }, s);
    const series = [[1, "var(--series-2)", "First innings"], [2, "var(--accent)", "Chase"]];
    series.forEach(([inn, col, lab]) => {
      const pts = D.calibration.filter((r) => r.innings === inn).sort((a, b) => a.bin - b.bin);
      el("path", { d: pts.map((r, i) => `${i ? "L" : "M"}${x(r.predicted)},${y(r.observed)}`).join(""), fill: "none", stroke: col, "stroke-width": 2, "stroke-linejoin": "round", "stroke-linecap": "round" }, s);
      pts.forEach((r) => {
        const c = el("circle", { cx: x(r.predicted), cy: y(r.observed), r: 4.5, fill: col, stroke: "var(--surface)", "stroke-width": 2 }, s);
        const hit = el("circle", { cx: x(r.predicted), cy: y(r.observed), r: 11, fill: "transparent" }, s);
        hover(hit, `<b>${lab}</b><br>Predicted ${pct(r.predicted, 1)} · observed ${pct(r.observed, 1)}<br>${nf.format(r.n)} balls`);
        void c;
      });
    });
    $("#cal-legend").innerHTML = series.map(([, c, l]) => `<span><i class="key" style="background:${c}"></i>${l}</span>`).join("") +
      '<span><i class="key" style="background:var(--muted);opacity:.6;height:1px"></i>Perfect calibration</span>';
    const h = (i) => D.meta.heldout.find((m) => m.model === "logit" && m.innings === i);
    $("#cal-note").textContent = `Calibration error ${pct(D.meta.ece["1"], 1)} (first innings) and ${pct(D.meta.ece["2"], 1)} (chase). ` +
      `Held-out log loss ${h(1).log_loss.toFixed(3)} vs ${h(1).log_loss_base.toFixed(3)} with no information (first innings), ` +
      `${h(2).log_loss.toFixed(3)} vs ${h(2).log_loss_base.toFixed(3)} (chase). Plain logistic regression beat spline and gradient-boosted alternatives in both innings.`;
  }

  // ---------- split-half
  function splitHalf() {
    const measures = [["pressure_raw", "Impact on pressure balls"], ["all_raw", "Impact on all balls"], ["uplift_raw", "Clutch uplift (pressure − usual)"]];
    const W = cw("#sh-chart"), narrow = W < 600, rowH = narrow ? 66 : 54, labW = narrow ? 30 : 230, pr = 50, pt = 6, pb = 30;
    const H = pt + rowH * measures.length + pb;
    const s = svg($("#sh-chart"), W, H);
    s.setAttribute("aria-label", "Split-half reliability (odd vs even matches)");
    const x = lin(-0.05, 0.3, labW, W - pr);
    [-0.05, 0, 0.1, 0.2, 0.3].forEach((t) => {
      el("line", { x1: x(t), x2: x(t), y1: pt, y2: H - pb, class: t === 0 ? "zero" : "gridline" }, s);
      text(s, x(t), H - pb + 16, t.toFixed(2), { "text-anchor": "middle" });
    });
    text(s, (labW + W - pr) / 2, H - 1, "Correlation between odd and even matches (r)", { "text-anchor": "middle", fill: "var(--muted)" });
    const roles = [["batters", "var(--navy)", "Batters"], ["bowlers", "var(--accent)", "Bowlers"]];
    measures.forEach(([k, lab], i) => {
      const cy = pt + rowH * i + rowH / 2 + (narrow ? 8 : 0);
      text(s, 0, narrow ? cy - 18 : cy + 4, lab, { fill: "var(--ink)" });
      roles.forEach(([role, col, rl], j) => {
        const v = D.reliability[role].split_half[k];
        const yy = cy + (j ? 7 : -7), x0 = x(0), x1 = x(v);
        const a = Math.min(x0, x1), w = Math.max(2, Math.abs(x1 - x0));
        const p = el("rect", { x: a, y: yy - 5, width: w, height: 10, rx: 3, fill: col }, s);
        hover(p, `<b>${rl}: ${lab}</b><br>r = ${v.toFixed(3)} (${D.reliability[role].split_half_players} players)`);
        text(s, (v >= 0 ? x1 + 6 : x0 + 6), yy + 4, v.toFixed(3), { fill: "var(--ink-2)" });
      });
    });
    $("#sh-legend").innerHTML = roles.map(([, c, l]) => `<span><i class="key" style="background:${c};height:8px"></i>${l}</span>`).join("");
    const rb = D.reliability;
    $("#sh-note").textContent = `Large clutch effects are ruled out: the largest spread of true clutch ability consistent with the data (90% bound) ` +
      `is ${rb.batters.clutch_bound.toFixed(4)} for batters and ${rb.bowlers.clutch_bound.toFixed(4)} for bowlers, against half-sample noise of ` +
      `${rb.batters.clutch_noise.toFixed(3)} and ${rb.bowlers.clutch_noise.toFixed(3)}. Small effects cannot be detected. So the rating leans on pressure balls ` +
      `(on average ${pct(rb.batters.weight_on_pressure_balls)} of a batter's own-data weight, ${pct(rb.bowlers.weight_on_pressure_balls)} of a bowler's) and borrows from ordinary balls only as far as clutch could not distort them.`;
  }

  // ---------- robustness table
  function robust() {
    const top = players().slice(0, 15);
    const t = $("#rtable");
    t.innerHTML = `<thead><tr><th>Main</th><th>Player</th>${D.variants.map((v) => `<th>${esc(v.label)}</th>`).join("")}<th>Top 10 in</th></tr></thead>
      <tbody>${top.map((p) => `<tr data-pid="${p.pid}"><td class="c">${p.rank}</td><td><button type="button" class="link">${esc(p.name)}</button></td>${D.variants.map((v) => {
        const r = p[v.key];
        return `<td class="c ${r == null ? "na" : r <= 10 ? "t10" : r <= 20 ? "t20" : ""}">${r == null ? "–" : r}</td>`;
      }).join("")}<td class="sum">${p.variants_top10}/${p.variants_eligible}</td></tr>`).join("")}</tbody>`;
    t.querySelectorAll("tbody tr").forEach((tr) => tr.addEventListener("click", () => openPlayer(+tr.dataset.pid)));
  }

  // ---------- wiring
  function select(pid, fromKey) {
    state.sel[state.role] = pid;
    rateChart();
    detail();
    if (fromKey) { const g = document.querySelector(`#rate-chart [data-pid="${pid}"]`); if (g) g.focus(); }
  }
  function openPlayer(pid) {
    select(pid);
    const d = $("#detail");
    d.setAttribute("tabindex", "-1");
    d.scrollIntoView({ block: "start" });
    d.focus({ preventScroll: true });
  }
  function setRole(role) {
    state.role = role;
    document.querySelectorAll(".seg button").forEach((b) => b.setAttribute("aria-pressed", String(b.dataset.role === role)));
    document.querySelectorAll(".role-name").forEach((n) => (n.textContent = role));
    const e = D.meta.eligibility[role === "batters" ? "bat" : "bowl"];
    $("#elig-note").textContent = `${players().length} ${role} with at least ${e.hp_balls} high-pressure balls across at least ${e.hp_inns} innings, and 60 ordinary balls. Sort by any column; pick a player to open their evidence.`;
    if (state.sort.key.endsWith("_hp") || state.sort.key.endsWith("_ord")) state.sort = { key: "rank", dir: 1 };
    rateChart(); detail(); table(); robust();
  }

  header();
  document.querySelectorAll(".seg button").forEach((b) => b.addEventListener("click", () => setRole(b.dataset.role)));
  $("#search").addEventListener("input", (e) => { state.q = e.target.value; table(); });
  heat($("#heat-hero"), 2); heat($("#heat-1"), 1); heatScale();
  swing(); decided(); calibration(); splitHalf();
  setRole("batters");
  addEventListener("scroll", hideTip, { passive: true });
  // scroll reveals: once, ~15% visible, small stagger between siblings
  const io = "IntersectionObserver" in window ? new IntersectionObserver((es) => es.forEach((e) => {
    if (e.isIntersecting) { e.target.classList.add("in"); io.unobserve(e.target); }
  }), { threshold: 0.12 }) : null;
  document.querySelectorAll(".reveal").forEach((n) => {
    const sib = [...n.parentElement.children].filter((x) => x.classList.contains("reveal"));
    n.style.setProperty("--d", `${Math.min(3, sib.indexOf(n)) * 0.08}s`);
    if (io) io.observe(n); else n.classList.add("in");
  });
  let lastW = innerWidth, rt = 0;
  addEventListener("resize", () => {
    if (innerWidth === lastW) return;
    lastW = innerWidth;
    clearTimeout(rt);
    rt = setTimeout(() => { rateChart(); heat($("#heat-hero"), 2); heat($("#heat-1"), 1); swing(); decided(); calibration(); splitHalf(); }, 150);
  });
})();
